package com.finflow.apigateway; import org.springframework.context.annotation.*; import org.springframework.security.config.web.server.ServerHttpSecurity; import org.springframework.security.web.server.SecurityWebFilterChain; @Configuration class SecurityConfig{@Bean SecurityWebFilterChain chain(ServerHttpSecurity h){return h.csrf(ServerHttpSecurity.CsrfSpec::disable).authorizeExchange(x->x.pathMatchers("/api/v1/auth/**","/actuator/health/**").permitAll().anyExchange().permitAll()).build();}}